<template><ion-page><ion-content class="auth-content"><main class="auth-card"><div class="auth-logo"><ion-icon :icon="imagesOutline" /></div><div class="brand"><span class="eyebrow">BEM-VINDO DE VOLTA</span><h1>Entre na sua<br><strong>galeria.</strong></h1><p>Suas memórias, sempre por perto.</p></div><ion-list lines="none"><ion-item><ion-icon slot="start" :icon="mailOutline" /><ion-input v-model="email" type="email" label="E-mail" label-placement="stacked" placeholder="voce@email.com" /></ion-item><ion-item><ion-icon slot="start" :icon="lockClosedOutline" /><ion-input v-model="password" type="password" label="Senha" label-placement="stacked" placeholder="Digite sua senha" /></ion-item></ion-list><ion-button expand="block" class="auth-submit" :disabled="loading" @click="submit">{{ loading ? 'Entrando...' : 'Entrar na galeria' }}<ion-icon slot="end" :icon="arrowForwardOutline" /></ion-button><p class="auth-link">Ainda não possui uma conta? <router-link to="/cadastro">Crie agora</router-link></p></main></ion-content></ion-page></template>
<script setup lang="ts">
import { ref } from 'vue'; import { IonButton, IonContent, IonIcon, IonInput, IonItem, IonList, IonPage, toastController } from '@ionic/vue'; import { arrowForwardOutline, imagesOutline, lockClosedOutline, mailOutline } from 'ionicons/icons'; import { useRouter } from 'vue-router'; import { login } from '@/services/auth';
const router = useRouter(); const email = ref(''); const password = ref(''); const loading = ref(false);
async function submit() { loading.value = true; try { if (await login(email.value, password.value)) return router.replace('/home'); const toast = await toastController.create({ message: 'E-mail ou senha inválidos.', color: 'danger', duration: 2200 }); await toast.present(); } finally { loading.value = false; } }
</script>
